#include <iostream>
#include <vector>

int main() {
    std::vector<int> numeros{1, 2, 3, 4};
    std::vector<int> cuadrados;
    for (int n : numeros) {
        if (n % 2 == 0) cuadrados.push_back(n * n);
    }
    for (int c : cuadrados) std::cout << c << " ";
    std::cout << std::endl;
    return 0;
}
